package it.carmine.streamplayer;
import android.app.*;import android.content.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Apple TV/Prime inspired VOD home, optimized for DPAD and the R. ITA palette. */
public class VodActivity extends Activity {
 private final ExecutorService worker=Executors.newFixedThreadPool(4);private final Handler ui=new Handler(Looper.getMainLooper());private ArtworkStore artwork;private FrameLayout root,heroFrame;private LinearLayout rows;private ImageView heroImage;private TextView heroTitle,heroMeta,heroPlot,heroDots,status;private VodDrawer.Controller drawer;private final List<VodSource.Title> carousel=new ArrayList<>();private int carouselIndex;private boolean destroyed,homeInitialized,homeRefreshing;
 private final Runnable rotate=new Runnable(){public void run(){if(destroyed||carousel.isEmpty())return;carouselIndex=(carouselIndex+1)%carousel.size();showCarousel();ui.postDelayed(this,7000);}};
 protected VodSource.Fetcher fetcher(){return VodSource.HTTP;}protected boolean imagesEnabled(){return true;}private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(UiTheme.TEXT);t.setTypeface(UiTheme.medium(this));return t;}private Button button(String value){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setTextSize(14);b.setMinWidth(0);b.setMinimumWidth(0);UiTheme.navigation(b);return b;}
 private Drawable cardFocus(){StateListDrawable states=new StateListDrawable();GradientDrawable f=new GradientDrawable();f.setColor(0xff242526);f.setStroke(dp(3),UiTheme.AMBER);f.setCornerRadius(dp(9));states.addState(new int[]{android.R.attr.state_focused},f);states.addState(new int[]{android.R.attr.state_pressed},f);GradientDrawable n=new GradientDrawable();n.setColor(0xff202125);n.setCornerRadius(dp(9));states.addState(new int[]{},n);return states;}
 @Override public void onCreate(Bundle state){super.onCreate(state);VodNetwork.initialize(this);getWindow().getDecorView().setSystemUiVisibility(5894);artwork=new ArtworkStore(this,imagesEnabled());root=new FrameLayout(this);root.setBackgroundColor(0xff151619);setContentView(root);ScrollView scroll=new ScrollView(this);scroll.setTag("vodHomeScroll");scroll.setFillViewport(true);root.addView(scroll,new FrameLayout.LayoutParams(-1,-1));rows=new LinearLayout(this);rows.setOrientation(LinearLayout.VERTICAL);rows.setPadding(dp(22),dp(14),dp(22),dp(28));scroll.addView(rows);buildCarousel();addSearch();status=text("Catalogo TMDB · preparazione…",12);status.setTextColor(0xffaaa9a5);rows.addView(status,new LinearLayout.LayoutParams(-1,dp(30)));drawer=VodDrawer.attach(this,root,heroFrame);loadHome();}
 private void buildCarousel(){heroFrame=new FrameLayout(this);heroFrame.setTag("vodHero");heroFrame.setFocusable(true);heroFrame.setClickable(true);heroFrame.setBackground(cardFocus());rows.addView(heroFrame,new LinearLayout.LayoutParams(-1,dp(330)));heroImage=new ProgrammeArtwork(this);heroImage.setScaleType(ImageView.ScaleType.CENTER_CROP);heroFrame.addView(heroImage,new FrameLayout.LayoutParams(-1,-1));GradientDrawable shade=new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,new int[]{0xf8151619,0xd0151619,0x30151619,0xa0151619});View overlay=new View(this);overlay.setBackground(shade);heroFrame.addView(overlay,new FrameLayout.LayoutParams(-1,-1));LinearLayout copy=new LinearLayout(this);copy.setOrientation(LinearLayout.VERTICAL);copy.setPadding(dp(30),dp(42),dp(18),dp(22));heroFrame.addView(copy,new FrameLayout.LayoutParams((int)(getResources().getDisplayMetrics().widthPixels*.55f),-1,Gravity.START));TextView label=text("NOVITÀ TMDB",13);label.setTextColor(UiTheme.AMBER);copy.addView(label);heroTitle=text("R. ITA VOD",32);copy.addView(heroTitle);heroMeta=text("Catalogo TMDB · fonte VixSrc",14);heroMeta.setTextColor(UiTheme.AMBER);copy.addView(heroMeta);heroPlot=text("Le novità vengono aggiornate automaticamente.",16);heroPlot.setMaxLines(4);copy.addView(heroPlot,new LinearLayout.LayoutParams(-1,0,1));heroDots=text("",18);heroDots.setTextColor(UiTheme.AMBER);copy.addView(heroDots);heroFrame.setOnClickListener(v->{if(!carousel.isEmpty())openTitle(carousel.get(carouselIndex));});heroFrame.setOnKeyListener((v,key,e)->{if(e.getAction()!=KeyEvent.ACTION_DOWN||carousel.isEmpty())return false;if(key==KeyEvent.KEYCODE_DPAD_LEFT){moveCarousel(-1);return true;}if(key==KeyEvent.KEYCODE_DPAD_RIGHT){moveCarousel(1);return true;}return false;});}
 private void addSearch(){Button search=button("⌕  Cerca film e serie TV  ·  Anno  ·  Generi");search.setTag("vodHomeSearch");search.setOnClickListener(v->startActivity(new Intent(this,VodCatalogueActivity.class).putExtra("searchPage",true).putExtra("sectionTitle","Cerca nel catalogo").putExtra("startMode",1)));rows.addView(search,new LinearLayout.LayoutParams(-1,dp(60)));}
 private void moveCarousel(int delta){carouselIndex=(carouselIndex+delta+carousel.size())%carousel.size();showCarousel();scheduleCarousel();}private void scheduleCarousel(){ui.removeCallbacks(rotate);ui.postDelayed(rotate,7000);}private void showCarousel(){if(carousel.isEmpty())return;VodSource.Title t=carousel.get(carouselIndex);heroTitle.setText(t.name);String genres=android.text.TextUtils.join(" · ",VodCatalogue.genres(t));heroMeta.setText((t.series()?"Serie TV":"Film")+(t.year.isEmpty()?"":" · "+t.year)+(genres.isEmpty()?"":" · "+genres));heroPlot.setText(t.plot.isEmpty()?"Premi OK per aprire la scheda.":t.plot);StringBuilder dots=new StringBuilder();for(int i=0;i<carousel.size();i++)dots.append(i==carouselIndex?"● ":"○ ");heroDots.setText(dots.toString().trim()+"    ◀  ▶");artwork.bind(heroImage,t.json.optString("_backdrop_url",t.poster),new ColorDrawable(0xff202125));}
 private void loadHome(){final String key=TmdbClient.key(this);if(key.isEmpty()){status.setText("TMDB non configurato");return;}worker.submit(()->{try{List<VodSource.Title> trending=TmdbClient.trending(key,fetcher()),news=TmdbClient.newReleases(key,fetcher()),movies=TmdbClient.popularMovies(key,fetcher()),shows=TmdbClient.popularShows(key,fetcher());VodSettings.Source tmdb=new VodSettings.Source("tmdb","TMDB","https://www.themoviedb.org","tmdb");List<VodSource.Title> history=VodLibrary.titles(this,tmdb,true);List<VodSource.Title> suggested=TmdbClient.recommendations(history.isEmpty()?null:history.get(0),key,fetcher());runOnUiThread(()->{if(destroyed)return;status.setText("Catalogo TMDB · Fonte video "+VodSession.video(this).name+" · disponibilità italiana quando dichiarata");carousel.clear();carousel.addAll(news.subList(0,Math.min(6,news.size())));if(carousel.isEmpty())carousel.addAll(trending.subList(0,Math.min(6,trending.size())));carouselIndex=0;showCarousel();scheduleCarousel();if(!history.isEmpty())addRow("Continua a guardare",history,20,true);List<VodSource.Title> watch=VodLibrary.watchlistTitles(this,tmdb);if(!watch.isEmpty())addRow("Da vedere",watch,20,false);addRow("Novità",news,20,false);addRow("Top 10 della settimana",trending,10,false);addRow("Consigliati per te",suggested,20,false);addPlatforms();addRow("Film",movies,20,false);addRow("Serie TV",shows,20,false);heroFrame.requestFocus();homeInitialized=true;homeRefreshing=false;});}catch(Exception e){runOnUiThread(()->{if(!destroyed)status.setText("Catalogo TMDB non disponibile · "+VodNetwork.error(e));});}});}
 private void refreshHome(){if(!homeInitialized||homeRefreshing)return;homeRefreshing=true;while(rows.getChildCount()>3)rows.removeViewAt(3);status.setText("Aggiornamento libreria…");loadHome();}
 private String rowKind(String label){if(label.equals("Novità"))return "novita";if(label.equals("Film"))return "film";if(label.equals("Serie TV"))return "series";if(label.equals("Continua a guardare"))return "continue";if(label.equals("Da vedere"))return "watchlist";if(label.equals("Top 10 della settimana"))return "novita";return "novita";}
 private int rowMode(String label){if(label.equals("Film"))return 1;if(label.equals("Serie TV"))return 2;if(label.equals("Continua a guardare"))return 4;if(label.equals("Da vedere"))return 5;return 0;}
 private void addRow(String label,List<VodSource.Title> titles,int max,boolean progress){if(titles==null||titles.isEmpty())return;TextView heading=text(label,21);heading.setPadding(0,dp(15),0,dp(7));rows.addView(heading);HorizontalScrollView strip=new HorizontalScrollView(this);strip.setHorizontalScrollBarEnabled(false);LinearLayout line=new LinearLayout(this);line.setOrientation(LinearLayout.HORIZONTAL);strip.addView(line);rows.addView(strip,new LinearLayout.LayoutParams(-1,dp(progress?252:238)));for(int i=0;i<Math.min(max,titles.size());i++){View cell=card(titles.get(i),progress);line.addView(cell,new LinearLayout.LayoutParams(dp(150),dp(progress?244:230)));cell.setOnKeyListener((v,key,e)->{if(e.getAction()==KeyEvent.ACTION_DOWN&&key==KeyEvent.KEYCODE_DPAD_RIGHT&&line.indexOfChild(v)==line.getChildCount()-1)return true;return false;});}Button all=button("Vedi tutti  ›");all.setTag("vodSeeAll");all.setOnClickListener(v->VodDrawer.section(this,rowMode(label),rowKind(label),label,0,""));line.addView(all,new LinearLayout.LayoutParams(dp(150),dp(progress?244:230)));all.setOnKeyListener((v,key,e)->e.getAction()==KeyEvent.ACTION_DOWN&&key==KeyEvent.KEYCODE_DPAD_RIGHT);}
 private View card(VodSource.Title title,boolean withProgress){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(5),dp(5),dp(5),dp(5));card.setFocusable(true);card.setClickable(true);card.setBackground(cardFocus());ProgrammeArtwork poster=new ProgrammeArtwork(this);poster.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(poster,new LinearLayout.LayoutParams(-1,dp(184)));if(withProgress){JSONObject h=VodLibrary.latest(this,"tmdb",TmdbClient.identity(title));ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setProgress(VodLibrary.percent(h));bar.setProgressTintList(android.content.res.ColorStateList.valueOf(UiTheme.AMBER));card.addView(bar,new LinearLayout.LayoutParams(-1,dp(5)));}TextView name=text(title.name,13);name.setMaxLines(2);name.setGravity(Gravity.CENTER_HORIZONTAL);card.addView(name,new LinearLayout.LayoutParams(-1,dp(36)));artwork.bind(poster,title.poster,new ColorDrawable(0xff292a2e));card.setOnClickListener(v->openTitle(title));card.setOnLongClickListener(v->{VodLibrary.watchlist(this,"tmdb",title);Toast.makeText(this,"Da vedere aggiornato",Toast.LENGTH_SHORT).show();return true;});return card;}
 private void addPlatforms(){TextView heading=text("Esplora per piattaforma",21);heading.setPadding(0,dp(15),0,dp(7));rows.addView(heading);HorizontalScrollView strip=new HorizontalScrollView(this);strip.setHorizontalScrollBarEnabled(false);LinearLayout line=new LinearLayout(this);strip.addView(line);rows.addView(strip,new LinearLayout.LayoutParams(-1,dp(74)));for(Map.Entry<Integer,String> p:TmdbClient.PROVIDERS.entrySet()){Button b=button(p.getValue());b.setBackground(cardFocus());b.setOnClickListener(v->VodDrawer.section(this,0,"platform",p.getValue(),p.getKey(),p.getValue()));line.addView(b,new LinearLayout.LayoutParams(dp(150),dp(58)));}}
 private void openTitle(VodSource.Title t){startActivity(new Intent(this,VodCatalogueActivity.class).putExtra("startMode",t.series()?2:1).putExtra("openTmdbId",t.json.optLong("tmdb_id")).putExtra("sectionTitle",t.name).putExtra("directDetail",true));}void closeDrawer(){if(drawer!=null)drawer.hide();}@Override public void onBackPressed(){if(drawer.open())drawer.hide();else drawer.show();}@Override protected void onResume(){super.onResume();CloudSync.flush(this,false);if(homeInitialized)refreshHome();scheduleCarousel();}@Override protected void onPause(){ui.removeCallbacks(rotate);super.onPause();}@Override protected void onDestroy(){destroyed=true;ui.removeCallbacksAndMessages(null);worker.shutdownNow();if(artwork!=null)artwork.close();super.onDestroy();}
}
